-- =======================================================================
-- MIGRATION 014: FY2027 Authoritative Target Data
-- 
-- Sources: 9 authoritative target PDFs (HEADOFFICE, HELENA, JANE_S,
--          KOLISWA, KZN, MAGGIE, NATHALIE, SANDILE, SERGIO)
-- Grain: rep_id (or territory_id for KZN) × product_sku_id × financial_period_id
-- Channels (CELLAR_DOOR, EVENTS, EXPORTS, PVT_CLIENTS) deferred.
-- 
-- ASP values already in asp_versions table from migration 006.
-- The VALUES section of PDFs = BOTTLES × AVG SP (derived, not independent).
-- Only BOTTLES targets are stored here.
-- =======================================================================

DO $migration$ BEGIN

  -- Step 1: Remove the incorrect MVP seed (wrong territory-level figures)
  DELETE FROM targets WHERE target_set_id = 'b8dc1af2-88b4-f7ae-4799-72898968471b';
  DELETE FROM target_sets WHERE id = 'b8dc1af2-88b4-f7ae-4799-72898968471b';
  RAISE NOTICE 'Migration 014: removed incorrect MVP Gauteng seed';

  -- Step 2: Create FY2027 rep-level target set
    target_level, source_document, approved_by, approved_at, notes, created_by)
  VALUES ('c1a17f28-0000-4000-a000-000000000001', '711c05f1-fb11-13d3-71e6-5c7c926e5dfe',
    'FY2027 Rep & Territory Targets',
    TRUE, 'REP',
    'HEADOFFICE.pdf, HELENA.pdf, JANE_S.pdf, KOLISWA.pdf, MAGGIE.pdf,
NATHALIE.pdf, SANDILE.pdf, SERGIO.pdf',
    'NSM', NOW(),
    'Per-rep per-SKU monthly bottle targets for FY2027. Sources: 8 rep PDFs.
KZN loaded as territory target (no rep). Channels (Cellar Door, Events,
Exports, Private Clients) deferred. Werner Briedenhann: no source supplied.',
    'migration_014');

  -- Step 3: Create KZN territory-level target set (no rep available)
    target_level, source_document, approved_by, approved_at, notes, created_by)
  VALUES ('c1a17f28-0000-4000-a000-000000000002', '711c05f1-fb11-13d3-71e6-5c7c926e5dfe',
    'FY2027 KZN Territory Targets',
    TRUE, 'TERRITORY',
    'KZN.pdf',
    'NSM', NOW(),
    'KZN territory-level targets. No individual rep record exists for KZN.
Loaded as territory_id = KZN.',
    'migration_014');

  -- Step 4: Load all rep and territory target rows
  -- Only non-zero months are stored to minimise rows.
  -- Negative values (carry-overs) are treated as 0 for target purposes.

  RAISE NOTICE 'Migration 014: Head Office (HO001) → 196 target rows';

  RAISE NOTICE 'Migration 014: Helena Pires (HEL001) → 87 target rows';

  RAISE NOTICE 'Migration 014: Jane Simon (JAN001) → 132 target rows';

  RAISE NOTICE 'Migration 014: Koliswa Jayiya (KOL001) → 169 target rows';

  RAISE NOTICE 'Migration 014: KZN Territory (no rep) → 99 target rows';

  RAISE NOTICE 'Migration 014: Maggie Colman (MAG001) → 100 target rows';

  RAISE NOTICE 'Migration 014: Nathalie Watkins (NAT001) → 162 target rows';

  RAISE NOTICE 'Migration 014: Sandile Yende (SAN001) → 151 target rows';

  RAISE NOTICE 'Migration 014: Sergio King (SER001) → 183 target rows';

  RAISE NOTICE 'Migration 014 complete: 1279 target rows loaded.';
END $migration$;

-- Verify
SELECT COUNT(*) AS total_target_rows FROM targets;
SELECT ts.set_name, COUNT(*) AS rows
FROM targets t JOIN target_sets ts ON ts.id = t.target_set_id GROUP BY ts.set_name;